def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/wildfire/input/nifc_wildfires.csv'
    rows = []
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        for i in range(1, 51):
            line = f.readline()
            if not line:
                break
            rows.append({'line_no': i, 'raw': line.rstrip('\n')})
    return pd.DataFrame(rows)

